func (d *dlpComplianceRuleListDataSource) Configure(_ context.Context, req datasource.ConfigureRequest, _ *datasource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}
	d.client = req.ProviderData.(*clients.Client)
}

func (d *dlpComplianceRuleListDataSource) Read(ctx context.Context, req datasource.ReadRequest, resp *datasource.ReadResponse) {
	res, err := d.client.SCC.GetDlpComplianceRule(ctx, purview.GetDlpComplianceRuleParams{})
	if err != nil {
		resp.Diagnostics.AddError("Get-DlpComplianceRule failed", err.Error())
		return
	}
	var data dlpComplianceRuleListModel
	for _, obj := range res.Value {
		var e dlpComplianceRuleModel
		readDlpComplianceRule(ctx, obj, &e)
		e.Identity = types.StringValue(firstNonEmptyStr(getString(obj, "Identity"), getString(obj, "Guid"), getString(obj, "Name")))
		data.Items = append(data.Items, e)
	}
	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}
